import { HttpClient } from "@angular/common/http";
import { inject, Injectable } from "@angular/core";
import { catchError, of, switchMap, throwError } from "rxjs";
import { User, userStore } from "src/app/store/userStore";
import { environment } from "src/environments/environment.development";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor() {}

  private http = inject(HttpClient);
  private userStore = inject(userStore);

  fetchUsers() {
    return this.http.get<User[]>(`${environment.apiUrl}/user`);
  }

  getUser(id: number) {
    return this.http.get<User>(`${environment.apiUrl}/user/${id}`);
  }

  addUser(data: Omit<User, "id" | "token">) {
    return this.http.post<User>(`${environment.apiUrl}/auth/register`, data);
  }

  updateUser(user: Omit<User, "token" | "password">) {
    this.userStore.updateUser(user);
    const { id, ...userWithoutId } = user;

    return this.getUser(user.id).pipe(
      switchMap((prevUser) =>
        this.http
          .patch<User>(`${environment.apiUrl}/user/${user.id}`, userWithoutId)
          .pipe(
            catchError((error) => {
              this.userStore.updateUser(prevUser);
              return throwError(() => error);
            }),
          ),
      ),
    );
  }

  deleteUser(id: number) {
    return this.getUser(id).pipe(
      switchMap((prevUser) =>
        this.http.delete(`${environment.apiUrl}/users/${id}`).pipe(
          catchError((error) => {
            // this.userStore.addUser(prevUser);
            return throwError(() => error);
          }),
        ),
      ),
    );
  }

  getToken() {
    return localStorage.getItem("token");
  }
}
